tasks.solution:
const score = 78;
let grade = "";

// decide grade with if / else if / else
if (score >= 85) {
  grade = "A";
} else if (score >= 70) {
  grade = "B";
} else if (score >= 50) {
  grade = "C";
} else {
  grade = "D";
}

console.log("Grade:", grade);

