challenge.starter:
const planet = "Mars";
let info = "";

// give info a value with switch

console.log(planet, "→", info);

challenge.solution:
const planet = "Mars";
let info = "";

// give info a value with switch
switch (planet) {
  case "Mercury":
    info = "The closest planet";
    break;
  case "Mars":
    info = "The red planet";
    break;
  case "Jupiter":
    info = "The biggest planet";
    break;
  default:
    info = "Unknown planet";
}

console.log(planet, "→", info);

