project_task.solution:
let lives = 1;
let stars = 8;
let message = "";

// give message a value with if / else if / else
if (lives === 0) {
  message = "Game over!";
} else if (stars >= 10) {
  message = "Congratulations, you win!";
} else {
  message = `Keep going! ${10 - stars} stars left.`;
}

console.log(message);
